import { chipClasses, type ChipProps } from '@mui/material/Chip';
import type { Theme } from '@mui/material/styles';
import type { SystemStyleObject } from '@mui/system';
import { svTokens } from '../../theme/tokens';

export function chipStyles(
  theme: Theme,
  { color, size, variant }: Pick<ChipProps, 'color' | 'size' | 'variant'>
): SystemStyleObject<Theme> {
  const tokens = svTokens(theme);
  const palette = (theme.vars ?? theme).palette;
  const neutral = color === 'default';
  const filled = variant === 'filled';
  const surface = `var(--SvChip-surface, ${tokens.surface})`;
  const hover = `var(--SvChip-surface-hover, ${tokens.surfaceHover})`;
  const iconColor = neutral
    ? `var(--SvChip-icon-color, ${palette.text.secondary})`
    : 'inherit';

  return {
    height: size === 'small' ? '24px' : '28px',
    borderRadius: '8px',
    padding: filled ? '2px 8px' : '1px 7px',
    gap: '6px',
    fontFamily: theme.typography.fontFamily,
    fontSize: '13px',
    fontWeight: 500,
    lineHeight: '24px',
    letterSpacing: '-0.0025em',
    ...(neutral && {
      color: palette.text.primary,
      backgroundColor: filled ? surface : 'transparent',
      [`&.${chipClasses.clickable}:hover, &.${chipClasses.deletable}:hover`]: {
        backgroundColor: hover,
        '@media (hover: none)': {
          backgroundColor: filled ? surface : 'transparent',
        },
      },
    }),
    [`&.${chipClasses.clickable}:active`]: { boxShadow: 'none' },
    [`& .${chipClasses.icon}, & .${chipClasses.deleteIcon}, & .${chipClasses.avatar}`]:
      {
        margin: 0,
        width: '16px',
        height: '16px',
        fontSize: '16px',
        flexShrink: 0,
      },
    [`& .${chipClasses.icon}, & .${chipClasses.deleteIcon}`]: {
      color: iconColor,
    },
    [`& .${chipClasses.deleteIcon}:hover`]: { color: 'inherit' },
    [`&.${chipClasses.focusVisible}`]: {
      ...(neutral && { backgroundColor: hover }),
      outline: `2px solid ${tokens.focus}`,
      outlineOffset: '2px',
    },
    '@media (prefers-reduced-motion: reduce)': { transition: 'none' },
    '@media (forced-colors: active)': {
      border: '1px solid ButtonText',
      [`&.${chipClasses.focusVisible}`]: { outlineColor: 'Highlight' },
    },
  };
}
